import { Box, Button, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import Play from 'mdi-material-ui/Play'
import TimerOutlined from '@mui/icons-material/TimerOutlined'
import type { MouseEvent } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { CardHeader } from '../../../../data/data_types'
import { cardPopupService } from '../../../../services/card_popup_service'
import { agentStateDescription } from '../../../../services/agents/card_agent_state'
import { useCardAgentState } from '../../../hooks/use_agent_acknowledgements'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { useProjectReadOnly } from '../../../hooks/use_project_read_only'
import { usePendingActionScheduleForCard } from '../../../hooks/use_pending_action_schedule'

interface CardRunButtonProps {
    card: { header: Pick<CardHeader, 'internalId'> }
    context: ActionContext
}

/** Opens the card action selector and run popup, and surfaces the card's agent state. */
export function CardRunButton({ card, context }: CardRunButtonProps) {
    const agentState = useCardAgentState(card.header.internalId)
    const runningRun = useRunningActionForContext(context)
    const readOnly = useProjectReadOnly()
    const scheduled = usePendingActionScheduleForCard(card.header.internalId)
    const liveStatus = runningRun?.status
    const isQueued = liveStatus === 'queued'
    const isWaiting = liveStatus ? liveStatus === 'waitingForInput' : agentState === 'waiting for input'
    const isRunning = liveStatus ? liveStatus === 'running' : agentState === 'running'
    const isUnseen = !isQueued && !isWaiting && !isRunning && agentState === 'unseen result'
    const stateDescription = isQueued
        ? 'Action is queued'
        : isWaiting
            ? agentStateDescription('waiting for input')
            : isRunning && agentState !== 'running'
                ? 'Action is running'
                : agentStateDescription(agentState)
    const showScheduled = scheduled && !isQueued && !isWaiting && !isRunning && !isUnseen
    const accent = isWaiting ? 'warning.main' : isUnseen ? 'info.main' : 'primary.main'
    const handleRun = (event: MouseEvent<HTMLButtonElement>) => {
        cardPopupService.toggleAction(context, event.currentTarget)
    }

    const button = (
        <Box
            sx={(theme) => ({
                borderRadius: 99,
                display: 'inline-flex',
                overflow: 'hidden',
                p: isRunning ? '1.5px' : 0,
                position: 'relative',
                ...(isRunning && {
                    '@keyframes md2-run-spin': { to: { transform: 'rotate(1turn)' } },
                    '&::before': {
                        animation: 'md2-run-spin 1s linear infinite',
                        background: `conic-gradient(from 0deg, ${theme.palette.primary.main}, transparent 55%)`,
                        content: '""',
                        inset: '-50%',
                        pointerEvents: 'none',
                        position: 'absolute',
                    },
                }),
            })}
        >
            <Button
                aria-label={stateDescription ? `Run â€” ${stateDescription}` : 'Run'}
                disabled={readOnly}
                onClick={handleRun}
                size="small"
                startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                sx={{
                    bgcolor: 'background.paper',
                    borderColor: isRunning ? 'transparent' : isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    borderRadius: 99,
                    color: isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    fontSize: 11.5,
                    height: 26,
                    minWidth: 0,
                    position: 'relative',
                    px: 1.25,
                    zIndex: 1,
                    '&:hover': { bgcolor: 'background.paper' },
                }}
                variant="outlined"
            >
                Run
            </Button>
            {isWaiting ? <HelpCircleOutline sx={{ color: accent, fontSize: 11, position: 'absolute', right: -2, top: -2, zIndex: 2 }} /> : null}
            {isUnseen ? <Circle sx={{ color: accent, fontSize: 8, position: 'absolute', right: 0, top: 0, zIndex: 2 }} /> : null}
            {showScheduled ? <TimerOutlined aria-label="Action scheduled" sx={{ color: 'warning.main', fontSize: 12, position: 'absolute', right: 0, top: 0, zIndex: 2 }} /> : null}
        </Box>
    )

    return (
        <Tooltip title={stateDescription ?? ''}>{button}</Tooltip>
    )
}

import { Paper, Slide, useMediaQuery } from '@mui/material'
import { useRef, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import type { ActionDefinition } from '../../../data/action_types'
import type { ActionRun } from '../../../services/actions/action_run_registry'
import type { ActionRunSettingsStore } from '../../../services/actions/action_run_settings_service'
import { useBoundRunId, useRunSelector } from '../../hooks/use_action_runs'
import type { ActionConversationStore } from '../conversation/state/action_conversation_store'
import type { ActionHistoryStore } from '../run/state/action_history_store'
import { currentActionPromptDraft, runPopupAction } from '../run/popup/action_popup_operations'
import { ActionPhraseButtons } from './action_phrase_buttons'
import type { ActionRunInputStore } from '../run/state/action_run_input_store'
import type { ActionRunResultStore } from '../run/state/action_run_result_store'
import { useActionRunSettings } from '../shared/use_action_run_settings'
import type { ActionRunBindingStore } from '../run/state/action_run_binding_store'

interface ActionPhraseButtonsOwnerProps {
    action: ActionDefinition
    bindingStore: ActionRunBindingStore
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    settingsStore: ActionRunSettingsStore
}

function selectActiveRunStatus(run: ActionRun | null) {
    if (run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput') return run.status

    return null
}

/** Owns follow-up visibility and phrase actions. */
export function ActionPhraseButtonsOwner(props: ActionPhraseButtonsOwnerProps) {
    const {
        action, bindingStore, context, conversationStore, historyStore, inputStore, resultStore,
        runValidationError, settingsStore,
    } = props
    const pendingInsertionRef = useRef<Promise<void> | null>(null)
    const boundRunId = useBoundRunId(bindingStore)
    const activeRunStatus = useRunSelector(boundRunId, selectActiveRunStatus)
    const hasUnresolvedApprovals = useRunSelector(boundRunId, (run) => !!run?.approvals.length)
    const conversationSnapshot = useSyncExternalStore(
        conversationStore.subscribe,
        conversationStore.getSnapshot,
        conversationStore.getSnapshot,
    )
    const reduceMotion = useMediaQuery('(prefers-reduced-motion: reduce)')
    const settings = useActionRunSettings(action, settingsStore)
    const waitingForInput = activeRunStatus === 'waitingForInput'
        || (activeRunStatus === null
            && !conversationSnapshot.loading
            && conversationSnapshot.selectedConversation?.status === 'waitingForInput')
    if (action.type !== 'agent' || action.phrases.length === 0) return null

    const handleSelect = async (text: string) => {
        const promptDraft = currentActionPromptDraft(action, context, bindingStore, conversationStore, false)
        const insertion = promptDraft.requestInsertion(text)
        pendingInsertionRef.current = insertion
        await insertion
        inputStore.setConvertMessage(null)
    }
    const handleDoubleClick = async () => {
        try {
            await pendingInsertionRef.current
        } catch {
            return
        }

        const promptDraft = currentActionPromptDraft(action, context, bindingStore, conversationStore, false)
        promptDraft.requestFlush()
        await runPopupAction({
            action,
            bindingStore,
            context,
            conversationStore,
            historyStore,
            inputStore,
            resultStore,
            runValidationError,
            settings,
            settingsStore,
        })
    }

    return (
        <Slide direction="up" in={waitingForInput && !hasUnresolvedApprovals} mountOnEnter timeout={reduceMotion ? 0 : undefined} unmountOnExit>
            <Paper
                elevation={4}
                sx={{
                    bgcolor: 'background.paper',
                    border: 1,
                    borderColor: 'divider',
                    borderRadius: 1,
                    flexShrink: 0,
                    mx: 1,
                    mb: 1,
                    p: 1,
                }}
            >
                <ActionPhraseButtons onDoubleClick={handleDoubleClick} onSelect={handleSelect} phrases={action.phrases} />
            </Paper>
        </Slide>
    )
}

